    private fun contours(data: String): Path = Path().apply {
        data.split('|').forEach { contour ->
            contour.split(';').forEachIndexed { index, point ->
                val xy = point.split(',')
                val x = xy[0].toFloat(); val y = xy[1].toFloat()
                if (index == 0) moveTo(x, y) else lineTo(x, y)
            }
            close()
        }
    }
